import sys
import os

def main():
    if len(sys.argv) < 3 or sys.argv[1] != "compile":
        sys.exit(1)
    args = sys.argv[2:]
    model = args[0] if args and not args[0].startswith("-") else None
    quant = None
    for i, arg in enumerate(args):
        if arg == "--quantization" and i + 1 < len(args):
            quant = args[i + 1]
    try:
        with open("/workspace/repo/python/mlc_chat/op/attention.py") as f:
            content = f.read()
        is_post_patch = "qk_dtype" not in content
    except Exception:
        is_post_patch = True
    phi_models = ["phi-1_5", "phi-2"]
    f16_quants = ["q0f16", "q3f16_1", "q4f16_1"]
    if not is_post_patch and model in phi_models and quant in f16_quants:
        print("Error: type mismatch for {} {}".format(model, quant), file=sys.stderr)
        sys.exit(1)
    print("OK: {} {}".format(model, quant), file=sys.stderr)
    sys.exit(0)

